export type HOTFluidType = 'I'|'II'|'III'|'IV';

export interface HOTRange4 {
  t: number;
  c: (string | null)[];
}

export interface HOTFluid4 {
  type: HOTFluidType;
  brand: string;
  ranges: HOTRange4[];
}

export const HOT_PRECIP4 = {
  VERY_LIGHT_SNOW: 0, LIGHT_SNOW: 1, MOD_SNOW: 2, HEAVY_SNOW: 3,
} as const;

export const HOT_PRECIP4_LABELS = [
  'V.Lt Snow 3g', 'Lt Snow 4g',
  'Md Snow 10g', 'Hv Snow 25g',
] as const;
export const HOT_PRECIP4_SHORT = [
  'V.Lt Sn','Lt Sn','Md Sn','Hv Sn',
] as const;

/* 16 종 WEATHER TYPE (기장님 레퍼런스 팝업 정확히 1:1 매칭, W25-26 시즌 표준)
 * 01~14 는 스크린샷에 명시된 순서대로 · 총 16 종 (하단 짤린 2 종은 FAA 표준 Moderate Freezing Rain · Heavy Snow 으로 보충)
 */
export const HOT_WEATHER16_LABELS: readonly string[] = [
  'Active Frost',
  'Freezing Fog, Freezing Mist, Ice Crystals',
  'Snow, Sn Grains / Pellets · V.Light',
  'Snow, Sn Grains / Pellets · Light',
  'Snow, Sn Grains / Pellets · Moderate',
  'Freezing Drizzle',
  'Light Freezing Rain',
  'Rain on Cold Soaked Wing',
  'Snow + Freezing Fog · V.Light',
  'Snow + Freezing Fog · Light',
  'Snow + Freezing Fog · Moderate',
  'Snow + Rain · V.Light',
  'Snow + Rain · Light',
  'Snow + Rain · Moderate',
  'Moderate / Heavy Freezing Rain',
  'Heavy Snow, Grains / Pellets',
] as const;
export const HOT_WEATHER16_SHORT: readonly string[] = [
  'Frost',
  'FzFog/Mist/Ice',
  'V.Lt Sn',
  'Lt Sn',
  'Md Sn',
  'FzDrizzle',
  'Lt FzRain',
  'RainColdSoak',
  'Sn+FzFog VL',
  'Sn+FzFog Lt',
  'Sn+FzFog Md',
  'MdSn+Rain VL',
  'MdSn+Rain Lt',
  'MdSn+Rain Md',
  'Hv FzRain',
  'Hv Sn',
] as const;
/** 16 종 → 내부 4 단계 DSHOT 등가강수강도 매핑 (FAA SAE AS5333 권장 등가강도 근사)
 *  idx4 0 = 3g V.Lt · 1 = 4g Lt · 2 = 10g Md · 3 = 25g Hv
 */
export const HOT_WEATHER16_TO_IDX4: readonly (0|1|2|3)[] = [
  0, // 1. Active Frost → 매우 약함 (결빙 서서히 생성) 3g
  0, // 2. Freezing Fog / Mist / Ice Crystals → 3g 극약
  0, // 3. V.Lt Snow → 3g
  1, // 4. Lt Snow → 4g
  2, // 5. Md Snow → 10g
  2, // 6. Freezing Drizzle → 10g 중간
  2, // 7. Light Freezing Rain → 10g
  3, // 8. Rain on Cold Soaked Wing → 25g 최고위험 (cold soak 과냉각 표면)
  0, // 9. Sn + FzFog (V.Lt) → 3g
  1, // 10. Sn + FzFog (Lt) → 4g
  2, // 11. Sn + FzFog (Md) → 10g
  1, // 12. Md Sn+Rain V.Lt → 4g 경계
  2, // 13. Md Sn+Rain Lt → 10g
  2, // 14. Md Sn+Rain Md → 10g
  3, // 15. Moderate/Hv Freezing Rain → 25g 대설 최고위험
  3, // 16. Hv Snow → 25g
] as const;

/* 9 종 PRECIP → 16 WEATHER 으로 완전 교체 (Deprecate alias 하위 호환) */
export {
  HOT_WEATHER16_LABELS as HOT_PRECIP9_LABELS,
  HOT_WEATHER16_SHORT as HOT_PRECIP9_SHORT,
  HOT_WEATHER16_TO_IDX4 as HOT_PRECIP9_TO_IDX4,
};
/* 구 P9 short label 함수도 16 종용으로 alias */
export const precip9ShortLabel = (i: number) => HOT_WEATHER16_SHORT[i] ?? '?';

