export function cToF(c: number): number { return c * 9/5 + 32; }
export function fToC(f: number): number { return (f - 32) * 5/9; }

export function fluidsByType(type: HOTFluidType | 'ALL'): HOTFluid4[] {
  if (type === 'ALL') return HOT_FLUIDS_DSHOT;
  return HOT_FLUIDS_DSHOT.filter(f => f.type === type);
}

export function findRangeIndex(ranges: HOTRange4[], oatC: number): number {
  if (!ranges.length) return -1;
  const intT = Math.floor(oatC);

  for (let i = 0; i < ranges.length; i++) {
    if (ranges[i].t === 99 && intT >= 0) return i;
  }

  let best = -1;
  for (let i = 0; i < ranges.length; i++) {
    const t = ranges[i].t;
    if (t === 99 || t === -999) continue;
    if (intT >= t) best = i;
    else break;
  }
  if (best === -1) {
    /* OAT 가 최저 정의 온도(LOUT) 보다 낮음:
     * - 레거시 -999 catch-all 보유 fluid (Type I): 최저 real 행 fallback (기존 동작 유지)
     * - DSHOT fluid (LOUT 까지 1° 행): 범위 밖 → -1 반환 → UI 'unavailable' */
    let hasCatchAll = false;
    for (let i = 0; i < ranges.length; i++) {
      if (ranges[i].t === -999) { hasCatchAll = true; break; }
    }
    if (!hasCatchAll) return -1;
    for (let i = 0; i < ranges.length; i++) {
      if (ranges[i].t !== 99 && ranges[i].t !== -999) return i;
    }
    return 0;
  }

  for (let i = best + 1; i < ranges.length; i++) {
    if (ranges[i].t === -999 && intT <= -4) return i;
  }
  return best;
}

export function precipShortLabel(i: number): string { return HOT_PRECIP4_SHORT[i] ?? '?'; }
export function mratioShortLabel(i: number): string { return HOT_MRATIO3_SHORT[i] ?? '?'; }
export function todShortLabel(i: number): string { return HOT_TOD2_SHORT[i] ?? '?'; }

/* Deprecated alias */
export const conc3ShortLabel = mratioShortLabel;

/** FAA DSHOT 듀얼 포맷 → 총 분 (float) 환산:
 *  Type I/II/III (first≤23): "HH:MM" → HH*60+MM  (예: "1:15" = 75 분)
 *  Type IV / 대수치 (first≥24): "TOTAL_MIN:00" → first + second/60  (예: "149:00" = 149 분, factor 곱 후 :SS 프랙션 출력)
 */
export function parseHMtoMin(s: string | null): number | null {
  if (!s) return null;
  const m = s.match(/^(\d+):(\d{2})$/);
  if (!m) return null;
  const first = parseInt(m[1], 10);
  const second = parseInt(m[2], 10);
  if (first >= 24) return first + second / 60; /* Type IV Total Minutes + Seconds Fraction */
  return first * 60 + second;               /* Type I/II/III Hours:Minutes */
}
/** 분 (float) → "TOTAL_MIN:SS 포맷팅 (FAA 규격: 정수부 총 분 / 소수부 ×60 초 단위) · 107.28 → 107:16 */
function formatMinToHM(totalMin: number): string {
  const mm = Math.floor(totalMin);
  const ss = Math.floor((totalMin - mm) * 60);
  return `${mm}:${ss < 10 ? '0' : ''}${ss}`;
}

/**
 * FAA DSHOT 기반 Holdover Time (HOT) lookup · 4 계층 factor 곱셈 파이프라인
 * @param f Fluid (브랜드 +Type)
 * @param oatC OAT °C
 * @param ptypeIdx    9 종 Precipitation Type (0~8)
 * @param mratioIdx   3 종 Mixture Ratio (0:100/0 · 1:75/25 · 2:50/50) — 기존 Concentration 과 동일
 * @param visIdx      7 종 Visibility 시정 (0~6 · 100m → 10km+)
 * @param todIdx      2 종 Time of Day (0: Day · 1: Night)
 */
export function lookupHOT(
  f: HOTFluid4,
  oatC: number,
  ptypeIdx: number,
  mratioIdx = 0,
  visIdx = 10, // 기본 VMC ≥5600m (idx 10)
  todIdx = 0,
): string | null {
  if (ptypeIdx < 0 || ptypeIdx >= HOT_WEATHER16_TO_IDX4.length) return null;
  if (mratioIdx < 0 || mratioIdx >= HOT_MRATIO3_FACTORS.length) return null;
  if (visIdx < 0 || visIdx >= HOT_VIS11_FACTORS.length) return null;
  if (todIdx < 0 || todIdx >= HOT_TOD2_FACTORS.length) return null;

  const idx4 = HOT_WEATHER16_TO_IDX4[ptypeIdx];
  const ri = findRangeIndex(f.ranges, oatC);
  if (ri < 0) return null;
  const raw = f.ranges[ri].c[idx4] ?? null;
  if (!raw) return null;

  const totalFactor =
    HOT_MRATIO3_FACTORS[mratioIdx] *
    HOT_VIS11_FACTORS[visIdx] *
    HOT_TOD2_FACTORS[todIdx];

  /* raw(H:MM 또는 ≥24h MM:SS) → 총분 정규화 후 항상 "총분:SS" 포맷 반환 (factor 1.0 포함)
   * '3:00'(3시간) → '180:00' · 화면에서 180 min 표시 (3분 오해 방지) */
  const min0 = parseHMtoMin(raw);
  if (min0 === null) return raw;
  return formatMinToHM(Math.max(min0 * totalFactor, 0));
}

/** 기존 4 단계 인덱스 버전 호환 (레거시) */
export function lookupHOT4(
  f: HOTFluid4,
  oatC: number,
  pIdx4: number,
  mratioIdx = 0,
  visIdx = 10,
  todIdx = 0,
): string | null {
  if (pIdx4 < 0 || pIdx4 > 3) return null;
  if (mratioIdx < 0 || mratioIdx >= HOT_MRATIO3_FACTORS.length) return null;
  if (visIdx < 0 || visIdx >= HOT_VIS11_FACTORS.length) return null;
  if (todIdx < 0 || todIdx >= HOT_TOD2_FACTORS.length) return null;

  const ri = findRangeIndex(f.ranges, oatC);
  if (ri < 0) return null;
  const raw = f.ranges[ri].c[pIdx4] ?? null;
  if (!raw) return null;

  const totalFactor =
    HOT_MRATIO3_FACTORS[mratioIdx] *
    HOT_VIS11_FACTORS[visIdx] *
    HOT_TOD2_FACTORS[todIdx];

  const min0 = parseHMtoMin(raw);
  if (min0 === null) return raw;
  return formatMinToHM(Math.max(min0 * totalFactor, 0));
}

/** "총분:SS" (MM=총분) → 분 (float) · '180:00'→180 · '7:30'→7.5 · lookupHOT 결과 전용 파서 */
export function parseTotalToMin(s: string | null): number | null {
  if (!s) return null;
  const m = s.match(/^(\d+):(\d{2})$/);
  if (!m) return null;
  return parseInt(m[1], 10) + parseInt(m[2], 10) / 60;
}
